const entrada = $input.all().map(i => i.json);
const falhou = entrada.find(l => l.error);

// ?periodo=7d mostra a semana; o resto, as últimas 24 h
const consulta = $('Abre o painel').first().json.query ?? {};
const período = consulta.periodo === '7d' ? '7d' : '24h';
const janela = (período === '7d' ? 7 * 24 : 24) * 60 * 60 * 1000;
const nomeDoPeríodo = período === '7d' ? '7 dias' : '24 h';

// o limite de memória do contêiner do bot (deploy.resources.limits.memory no compose.yaml)
const LIMITE_MB = 512;

const agora = Date.now();
const todas = entrada
  .filter(l => l.coletado_em)
  .map(l => ({ ...l, quando: new Date(l.coletado_em).getTime() }))
  .sort((a, b) => a.quando - b.quando);
const linhas = todas.filter(l => agora - l.quando <= janela);
const última = todas.at(-1);
const primeira = linhas[0];

const fuso = { timeZone: 'America/Sao_Paulo' };
const hora = quando => new Date(quando).toLocaleTimeString('pt-BR', { ...fuso, hour: '2-digit', minute: '2-digit' });
const diaEHora = quando => new Date(quando).toLocaleString('pt-BR', { ...fuso, day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
const rótulo = período === '7d' ? diaEHora : hora;
const número = valor => (valor ?? 0).toLocaleString('pt-BR', { maximumFractionDigits: 0 });

// ---- o banner do boot, o mesmo do console, desenhado em pixels ---------------------
const BANNER = [
  '▄▀█ █░░ █▀▀ █▀█ █░█   █▄▄ █▀█ ▀█▀',
  '█▀█ █▄▄ ██▄ █▀▀ █▀█   █▄█ █▄█ ░█░',
];

// cada caractere vira uma célula de 1×2, como no terminal: █ enche as duas metades, ▀ a
// de cima, ▄ a de baixo, e ░ é a trama fraca. Corridas vizinhas viram um retângulo só
const metades = { '█': [0, 1], '▀': [0], '▄': [1] };
const largura = Math.max(...BANNER.map(l => [...l].length));
const retângulos = [];
BANNER.forEach((linha, y) => {
  const letras = [...linha];
  for (const meio of [0, 1]) {
    for (let x = 0; x < letras.length; x++) {
      if (!metades[letras[x]]?.includes(meio)) continue;
      let fim = x;
      while (fim + 1 < letras.length && metades[letras[fim + 1]]?.includes(meio)) fim++;
      retângulos.push(`<rect x="${x}" y="${y * 2 + meio}" width="${fim - x + 1}" height="1"/>`);
      x = fim;
    }
  }
  letras.forEach((c, x) => {
    if (c === '░') retângulos.push(`<rect class="trama" x="${x}" y="${y * 2}" width="1" height="2"/>`);
  });
});
const banner = `<svg class="banner" viewBox="0 0 ${largura} 4" role="img" aria-label="AlephBot" shape-rendering="crispEdges">${retângulos.join('')}</svg>`;

// ---- o estado, na voz da Denia ------------------------------------------------------
const idadeMin = última ? Math.round((agora - última.quando) / 60000) : null;
const idade = idadeMin === null ? '' : idadeMin < 120 ? `${idadeMin} min` : `${Math.round(idadeMin / 60)} h`;
const estado = falhou ? 'sem-tabela' : !última ? 'vazio' : idadeMin <= 20 ? 'ok' : 'atrasado';

const fala = {
  ok: 'Tô de pé e anotando tudo.',
  atrasado: `Faz ${idade} que não anoto nada. Ou eu caí, ou o fluxo de stats parou.`,
  vazio: 'Ainda não anotei nada. Volta daqui a 15 minutos.',
  'sem-tabela': 'Ainda não tenho onde anotar: a tabela nasce na primeira coleta do fluxo de stats.',
}[estado];

const ÍCONES = {
  bom: '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3.5 8.5l3 3 6-7" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>',
  atenção: '<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M8 2.5l6 11H2z" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linejoin="round"/><path d="M8 6.5v3.2M8 11.6v.1" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>',
  neutro: '<svg viewBox="0 0 16 16" aria-hidden="true"><circle cx="8" cy="8" r="5" fill="none" stroke="currentColor" stroke-width="1.6"/></svg>',
};

const status = {
  ok: { classe: 'bom', texto: `Coletando. Última coleta às ${última ? hora(última.quando) : ''}.` },
  atrasado: { classe: 'atenção', texto: `Sem coleta há ${idade}. A última foi em ${última ? diaEHora(última.quando) : ''}.` },
  vazio: { classe: 'neutro', texto: 'Sem coletas ainda.' },
  'sem-tabela': { classe: 'neutro', texto: 'Sem coletas ainda.' },
}[estado];

// ---- os números de agora ------------------------------------------------------------
// a cor da variação só vale onde subir é bom; o resto muda sem julgamento
const variação = (campo, subirÉBom) => {
  if (!última || !primeira) return { texto: '', classe: '' };
  const diferença = (última[campo] ?? 0) - (primeira[campo] ?? 0);
  if (diferença === 0) return { texto: 'estável', classe: '' };
  const classe = subirÉBom === undefined ? '' : (diferença > 0) === subirÉBom ? 'melhor' : 'pior';
  return { texto: `${diferença > 0 ? '+' : '−'}${número(Math.abs(diferença))} em ${nomeDoPeríodo}`, classe };
};

const membros = variação('membros', true);
const servidores = variação('servidores', true);

const memória = última?.memoria_mb ?? 0;
const ocupação = Math.min(100, Math.round(memória / LIMITE_MB * 100));
const gravidade = ocupação >= 90 ? 'crítico' : ocupação >= 75 ? 'atenção' : 'normal';

// ---- os gráficos: uma escala por gráfico, no máximo três séries ----------------------
const gráficos = [
  { título: 'Pessoas', id: 'pessoas', séries: [['membros', 'Membros'], ['online', 'Online']] },
  { título: 'Música', id: 'musica', séries: [['players', 'Players abertos'], ['tocando', 'Tocando'], ['na_fila', 'Na fila']] },
  { título: 'Memória do bot', id: 'memoria', unidade: 'MB', séries: [['memoria_mb', 'Processo'], ['heap_mb', 'Heap do .NET']] },
  { título: 'Servidores', id: 'servidores', degrau: true, séries: [['servidores', 'Servidores']] },
].map(g => ({
  ...g,
  séries: g.séries.map(([campo, nome]) => ({ nome, valores: linhas.map(l => l[campo] ?? null) })),
}));

// o JSON vai dentro de um <script>: sem "<" cru, nada dele fecha a tag antes da hora
const dados = JSON.stringify({ rótulos: linhas.map(l => rótulo(l.quando)), gráficos })
  .replace(/</g, '\\u003c');

const legenda = g => g.séries.length < 2 ? '' : `
          <ul class="legenda">${g.séries.map((s, i) => `<li><span class="chave s${i + 1}"></span>${s.nome}</li>`).join('')}</ul>`;

const figuras = gráficos.map(g => `
      <figure class="grafico">
        <figcaption>
          <h2>${g.título}</h2>${legenda(g)}
        </figcaption>
        <div class="tela"><canvas id="g-${g.id}" role="img" aria-label="${g.título}: ${g.séries.map(s => s.nome).join(', ')} ao longo de ${nomeDoPeríodo}. Os números estão na tabela abaixo."></canvas></div>
      </figure>`).join('');

const colunas = ['Quando', 'Servidores', 'Membros', 'Online', 'Players abertos', 'Tocando', 'Na fila', 'Memória (MB)', 'Heap (MB)'];
const tabela = [...linhas].reverse().map(l => `
            <tr><th scope="row">${diaEHora(l.quando)}</th>${['servidores', 'membros', 'online', 'players', 'tocando', 'na_fila', 'memoria_mb', 'heap_mb'].map(c => `<td>${número(l[c])}</td>`).join('')}</tr>`).join('');

const conteúdo = linhas.length === 0
  ? `
    <p class="vazio">${estado === 'sem-tabela'
      ? 'Assim que o fluxo <strong>AlephBot · Histórico de stats</strong> rodar pela primeira vez, a tabela <code>aleph_stats</code> aparece e os gráficos começam a encher.'
      : `Nenhuma coleta nas últimas ${nomeDoPeríodo}. O fluxo <strong>AlephBot · Histórico de stats</strong> grava uma a cada 15 minutos: confira se ele está publicado.`}</p>`
  : `
    <section class="numeros" aria-label="Agora">
      <div class="heroi">
        <p class="rotulo">Membros</p>
        <p class="valor-heroi">${número(última.membros)}</p>
        <p class="variacao ${membros.classe}">${membros.texto}</p>
      </div>
      <dl class="stats">
        <div>
          <dt>Servidores</dt>
          <dd class="valor">${número(última.servidores)}</dd>
          <dd class="variacao ${servidores.classe}">${servidores.texto}</dd>
        </div>
        <div>
          <dt>Online agora</dt>
          <dd class="valor">${número(última.online)}</dd>
          <dd class="variacao">pessoas, sem contar bots</dd>
        </div>
        <div>
          <dt>Tocando agora</dt>
          <dd class="valor">${número(última.tocando)}</dd>
          <dd class="variacao">${!última.players ? 'nenhum player aberto' : última.players === 1 ? '1 player aberto' : `${número(última.players)} players abertos`}</dd>
        </div>
      </dl>
      <div class="medidor ${gravidade}">
        <p class="rotulo">Memória</p>
        <p class="medida"><span class="valor">${número(memória)} MB</span> de ${LIMITE_MB} MB</p>
        <div class="trilho" role="meter" aria-valuemin="0" aria-valuemax="${LIMITE_MB}" aria-valuenow="${Math.round(memória)}" aria-label="Memória do bot">
          <div class="preenchido" style="width: ${ocupação}%"></div>
        </div>
        <p class="variacao">${ocupação}% do limite do contêiner</p>
      </div>
    </section>

    <section class="graficos">${figuras}
    </section>

    <details class="tabela">
      <summary>Ver todos os números em tabela</summary>
      <div class="rolagem">
        <table>
          <thead><tr>${colunas.map(c => `<th scope="col">${c}</th>`).join('')}</tr></thead>
          <tbody>${tabela}
          </tbody>
        </table>
      </div>
    </details>`;

const html = `<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="refresh" content="300">
<meta name="color-scheme" content="dark light">
<title>AlephBot · Painel</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Sans:wght@400;500;600&display=swap" rel="stylesheet">
<style>
  /* as cores do console do bot (xterm-256: 234, 255, 250, 245, 141). As das séries saíram
     do validador do skill de dataviz: banda de luminosidade, croma, daltonismo e contraste */
  :root {
    color-scheme: dark;
    --fundo: #1c1c1c;
    --elevado: #262626;
    --tinta: #eeeeee;
    --tinta-2: #bcbcbc;
    --apagado: #8a8a8a;
    --grade: #2a2a2a;
    --base: #3a3a3a;
    --marca: #af87ff;
    --s1: #9f6df8;
    --s2: #2ca2a2;
    --s3: #a44a5c;
    --melhor: #4cc24c;
    --pior: #ff7b7b;
    --bom: #0ca30c;
    --atencao: #fab219;
    --critico: #d03b3b;
  }
  @media (prefers-color-scheme: light) {
    :root {
      color-scheme: light;
      --fundo: #fcfcfb;
      --elevado: #f0f0ee;
      --tinta: #1c1c1c;
      --tinta-2: #4e4e4e;
      --apagado: #6c6c6c;
      --grade: #e4e4e1;
      --base: #c8c8c4;
      --marca: #8a5cf0;
      --s1: #a67bf8;
      --s2: #14938d;
      --s3: #78395f;
      --melhor: #006300;
      --pior: #b42323;
    }
  }

  * { box-sizing: border-box; }
  body {
    margin: 0;
    background: var(--fundo);
    color: var(--tinta);
    font: 400 16px/1.5 "IBM Plex Sans", system-ui, sans-serif;
  }
  main { max-width: 1120px; margin: 0 auto; padding: 40px 32px 56px; }

  .topo { margin-bottom: 32px; }
  h1 { margin: 0; line-height: 0; }
  .banner { width: min(420px, 100%); height: auto; fill: var(--marca); }
  .banner .trama { opacity: .22; }
  .fala { margin: 14px 0 0; font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 15px; color: var(--tinta-2); }
  .fala .prompt { color: var(--marca); }

  .filtros { display: flex; flex-wrap: wrap; align-items: center; gap: 12px 24px; padding-bottom: 20px; border-bottom: 1px solid var(--grade); }
  .periodo { display: inline-flex; gap: 4px; }
  .periodo a {
    padding: 6px 12px; border-radius: 6px; border: 1px solid transparent;
    color: var(--tinta-2); text-decoration: none; font-size: 14px; font-weight: 500;
  }
  .periodo a:hover { border-color: var(--base); }
  .periodo a[aria-current="page"] { background: var(--elevado); border-color: var(--base); color: var(--tinta); }
  .periodo a:focus-visible, summary:focus-visible { outline: 2px solid var(--marca); outline-offset: 2px; }
  .status { display: inline-flex; align-items: center; gap: 8px; margin: 0; font-size: 14px; color: var(--tinta-2); }
  .status svg { width: 16px; height: 16px; flex: none; }
  .status.bom svg { color: var(--bom); }
  .status.atenção svg { color: var(--atencao); }
  .status.neutro svg { color: var(--apagado); }

  .numeros { display: grid; grid-template-columns: auto 1fr minmax(240px, 300px); gap: 40px; align-items: end; padding: 32px 0; border-bottom: 1px solid var(--grade); }
  .rotulo, dt { margin: 0; color: var(--tinta-2); font-size: 14px; }
  .valor-heroi { margin: 4px 0 0; font-size: 64px; line-height: 1; font-weight: 600; letter-spacing: -.02em; }
  .stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); gap: 24px; margin: 0; }
  .stats > div { padding-left: 16px; border-left: 1px solid var(--grade); }
  dd { margin: 0; }
  .valor { font-size: 28px; line-height: 1.2; font-weight: 600; margin-top: 4px; }
  .variacao { margin: 4px 0 0; font-size: 13px; color: var(--apagado); }
  .variacao.melhor { color: var(--melhor); }
  .variacao.pior { color: var(--pior); }
  .medida { margin: 4px 0 8px; color: var(--tinta-2); font-size: 14px; }
  .medida .valor { font-size: 28px; color: var(--tinta); margin-right: 4px; }
  .trilho { height: 8px; border-radius: 4px; background: color-mix(in srgb, var(--s1) 22%, transparent); overflow: hidden; }
  .preenchido { height: 100%; border-radius: 4px; background: var(--s1); }
  .medidor.atenção .trilho { background: color-mix(in srgb, var(--atencao) 22%, transparent); }
  .medidor.atenção .preenchido { background: var(--atencao); }
  .medidor.crítico .trilho { background: color-mix(in srgb, var(--critico) 22%, transparent); }
  .medidor.crítico .preenchido { background: var(--critico); }

  .graficos { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 48px; }
  .grafico { margin: 0; padding: 28px 0 24px; border-bottom: 1px solid var(--grade); }
  figcaption { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 8px 16px; margin-bottom: 16px; }
  h2 { margin: 0; font-size: 17px; font-weight: 600; }
  .legenda { display: flex; flex-wrap: wrap; gap: 4px 16px; margin: 0; padding: 0; list-style: none; font-size: 13px; color: var(--tinta-2); }
  .legenda li { display: inline-flex; align-items: center; gap: 6px; }
  .chave { width: 14px; height: 2px; border-radius: 1px; }
  .chave.s1 { background: var(--s1); }
  .chave.s2 { background: var(--s2); }
  .chave.s3 { background: var(--s3); }
  .tela { position: relative; height: 232px; }

  .tabela { margin-top: 32px; }
  summary { cursor: pointer; color: var(--tinta-2); font-size: 14px; font-weight: 500; }
  .rolagem { max-height: 420px; overflow: auto; margin-top: 12px; border: 1px solid var(--grade); border-radius: 6px; }
  table { width: 100%; border-collapse: collapse; font-size: 13px; font-variant-numeric: tabular-nums; }
  th, td { padding: 8px 12px; text-align: right; border-bottom: 1px solid var(--grade); white-space: nowrap; }
  th:first-child { text-align: left; }
  thead th { position: sticky; top: 0; background: var(--elevado); color: var(--tinta-2); font-weight: 500; }
  tbody th { font-weight: 400; color: var(--tinta-2); }

  .vazio { max-width: 60ch; padding: 32px 0; color: var(--tinta-2); }
  code { font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: .92em; }
  footer { margin-top: 32px; color: var(--apagado); font-size: 13px; }

  @media (max-width: 860px) {
    main { padding: 28px 16px 40px; }
    .numeros { grid-template-columns: 1fr; gap: 24px; }
    .graficos { grid-template-columns: 1fr; }
  }
</style>
</head>
<body>
<main>
  <header class="topo">
    <h1>${banner}</h1>
    <p class="fala"><span class="prompt">denia ›</span> ${fala}</p>
  </header>

  <div class="filtros">
    <nav class="periodo" aria-label="Período">
      <a href="?periodo=24h"${período === '24h' ? ' aria-current="page"' : ''}>Últimas 24 h</a>
      <a href="?periodo=7d"${período === '7d' ? ' aria-current="page"' : ''}>Últimos 7 dias</a>
    </nav>
    <p class="status ${status.classe}">${ÍCONES[status.classe]}${status.texto}</p>
  </div>
${conteúdo}

  <footer>A página se atualiza sozinha a cada 5 minutos. O n8n coleta de 15 em 15.</footer>
</main>
${linhas.length === 0 ? '' : `<script src="https://cdn.jsdelivr.net/npm/chart.js@4"></script>
<script>
  const { rótulos, gráficos } = ${dados};
  const css = getComputedStyle(document.documentElement);
  const cor = nome => css.getPropertyValue(nome).trim();
  const séries = [cor('--s1'), cor('--s2'), cor('--s3')];
  const superfície = cor('--fundo');

  Chart.defaults.font.family = '"IBM Plex Sans", system-ui, sans-serif';
  Chart.defaults.font.size = 12;
  Chart.defaults.color = cor('--apagado');
  Chart.defaults.animation = false;

  // a linha vertical que acompanha o ponteiro e acha o horário mais perto
  const mira = {
    id: 'mira',
    afterDatasetsDraw(chart) {
      const ativo = chart.tooltip?.getActiveElements?.() ?? [];
      if (!ativo.length) return;
      const x = ativo[0].element.x;
      const { top, bottom } = chart.chartArea;
      const ctx = chart.ctx;
      ctx.save();
      ctx.strokeStyle = cor('--base');
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(x, top);
      ctx.lineTo(x, bottom);
      ctx.stroke();
      ctx.restore();
    },
  };

  // o valor de agora na ponta de cada linha, com um ponto de anel na cor da superfície
  const ponta = {
    id: 'ponta',
    afterDatasetsDraw(chart) {
      const ctx = chart.ctx;
      const usados = [];
      chart.data.datasets.forEach((d, i) => {
        const meta = chart.getDatasetMeta(i);
        let j = d.data.length - 1;
        while (j >= 0 && d.data[j] == null) j--;
        if (j < 0) return;
        const p = meta.data[j];
        ctx.save();
        ctx.beginPath();
        ctx.arc(p.x, p.y, 6, 0, Math.PI * 2);
        ctx.fillStyle = superfície;
        ctx.fill();
        ctx.beginPath();
        ctx.arc(p.x, p.y, 4, 0, Math.PI * 2);
        ctx.fillStyle = d.borderColor;
        ctx.fill();
        // pontas que caem no mesmo lugar não empilham texto: a legenda e a tabela cobrem
        if (!usados.some(y => Math.abs(y - p.y) < 14)) {
          usados.push(p.y);
          ctx.fillStyle = cor('--tinta');
          ctx.font = '600 12px "IBM Plex Sans", system-ui, sans-serif';
          ctx.textBaseline = 'middle';
          ctx.fillText(Number(d.data[j]).toLocaleString('pt-BR', { maximumFractionDigits: 0 }), p.x + 10, p.y);
        }
        ctx.restore();
      });
    },
  };

  for (const g of gráficos) {
    const único = g.séries.length === 1;
    new Chart(document.getElementById('g-' + g.id), {
      type: 'line',
      data: {
        labels: rótulos,
        datasets: g.séries.map((s, i) => ({
          label: s.nome,
          data: s.valores,
          borderColor: séries[i],
          backgroundColor: único ? séries[i] + '1a' : séries[i],
          fill: único ? 'origin' : false,
          borderWidth: 2,
          borderCapStyle: 'round',
          borderJoinStyle: 'round',
          pointRadius: 0,
          pointHoverRadius: 0,
          pointStyle: 'line',
          tension: 0,
          stepped: g.degrau ? 'before' : false,
        })),
      },
      plugins: [mira, ponta],
      options: {
        maintainAspectRatio: false,
        layout: { padding: { right: 36, top: 8 } },
        interaction: { mode: 'index', intersect: false },
        plugins: {
          legend: { display: false },
          tooltip: {
            backgroundColor: cor('--elevado'),
            borderColor: cor('--base'),
            borderWidth: 1,
            titleColor: cor('--apagado'),
            bodyColor: cor('--tinta'),
            titleFont: { weight: '400' },
            bodyFont: { weight: '600' },
            padding: 10,
            cornerRadius: 6,
            usePointStyle: true,
            boxWidth: 14,
            boxPadding: 6,
            callbacks: {
              label: c => ' ' + (c.parsed.y ?? 0).toLocaleString('pt-BR', { maximumFractionDigits: 0 }) + (g.unidade ? ' ' + g.unidade : '') + '  ' + c.dataset.label,
            },
          },
        },
